-- Data for Name: _how_to_v_blocks_how_to_sections_steps; Type: TABLE DATA; Schema: public; Owner: payload
--

COPY public._how_to_v_blocks_how_to_sections_steps (_order, _parent_id, id, heading, swap_columns, image_id, use_content_repeater, rich_text, tooltip_enabled, tooltip_variant, tooltip_text, _uuid, tip_max_width_px, use_list_indentation, columns_proportion, mobile_image_id) FROM stdin;
1	177	733	Night 1: Measure & Soak	f	8	f	{"root": {"type": "root", "format": "", "indent": 0, "version": 1, "children": [{"tag": "ul", "type": "list", "start": 1, "format": "", "indent": 0, "version": 1, "children": [{"type": "listitem", "value": 1, "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Add 1 tablespoon of sprouting seeds to your clean mason jar (1 tablespoon yields approximately 1 cup of sprouts). ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null}, {"type": "listitem", "value": 2, "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Place the sprouting lid or cheesecloth onto the jar. ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null}, {"type": "listitem", "value": 3, "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Rinse the seeds thoroughly by adding filtered water to your jar. ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null}, {"type": "listitem", "value": 4, "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Swirl the water around and pour it out. Repeat this at least two times. ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null}, {"type": "listitem", "value": 5, "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Next, fill the jar with filtered water about 1 inch above the seeds. ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null}, {"type": "listitem", "value": 6, "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Leave the water in the jar overnight in a cabinet, closet, dark counter, or in the fridge to soak the seeds.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null}], "listType": "bullet", "direction": null}], "direction": null}}	t	proTip	{"root": {"type": "root", "format": "", "indent": 0, "version": 1, "children": [{"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Start your first batch right before bed in the evening as they need 8-12 hours to soak.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}], "direction": null}}	68e5703fcec99466f47ebf55	537	f	6-6	\N
2	177	734	Days 2-4: Drain, Rinse, & Shake	t	7	f	{"root": {"type": "root", "format": "", "indent": 0, "version": 1, "children": [{"tag": "ul", "type": "list", "start": 1, "format": "", "indent": 0, "version": 1, "children": [{"type": "listitem", "value": 1, "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "After 8-12 hours of soaking, drain then rinse the seeds thoroughly. ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null}, {"type": "listitem", "value": 2, "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "After rinsing, be sure to shake the water out of the jar really well. ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null}, {"type": "listitem", "value": 3, "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Try to encourage the seeds to coat and stick to the sides of the jar. ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null}, {"type": "listitem", "value": 4, "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Then, place the jar at an angle (in a dark and dry space) to drain any excess water. A dish rack or small bowl is helpful for encouraging draining. ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null}, {"type": "listitem", "value": 5, "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "Rinse and drain twice a day (morning and evening) with cool, filtered water to keep seeds fresh and to prevent mold. ", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null}, {"type": "listitem", "value": 6, "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "After a few days of draining and rinsing, you will notice the tiny sprouts beginning to form.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null}], "listType": "bullet", "direction": null}], "direction": null}}	t	important	{"root": {"type": "root", "format": "", "indent": 0, "version": 1, "children": [{"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [{"mode": "normal", "text": "To prevent mold or other issues with contamination, completely get rid of any excess water.", "type": "text", "style": "", "detail": 0, "format": 0, "version": 1}], "direction": null, "textStyle": "", "textFormat": 0}], "direction": null}}	68e57070cec99466f47ebf57	620	f	6-6	\N
