rection": null}], "listType": "bullet", "direction": null}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"type": "block", "fields": {"id": "6902883080904634a4c8b57b", "items": [], "heading": "RESOURCES", "blockName": "", "blockType": "collectionItemSlider", "usePlaceholders": true, "widthConstraint": false, "placeholderCount": 5, "placeholderImage": 2, "placeholderTitle": "Placeholder Image"}, "format": "", "version": 2}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}, {"type": "block", "fields": {"id": "6902884180904634a4c8b57c", "heading": "DID YOU MAKE THIS RECIPE?", "showIcon": true, "blockName": "", "blockType": "instagram", "paragraph": "Share a pic and tag @thedoggydish on Instagram", "textColor": "#FFFFFF", "backgroundColor": "#F6A944"}, "format": "", "version": 2}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "children": [], "direction": null, "textStyle": "", "textFormat": 0}], "direction": null}}	f
